//! Brand OS glyphs for sidebar rows and tabs.
//!
//! Filled brand marks come from [Simple Icons](https://github.com/simple-icons/simple-icons)
//! (24×24 path + brand hex), regenerated by `scripts/gen-simple-icons.py --write`.
//! Unknown / unsupported ids (e.g. Windows — not in Simple Icons) fall back to
//! the Lucide badge the row already carries.

use crate::icons::{commands, Cmd, Icon};

/// A resolved brand mark, or no mark.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum OsGlyph {
    Brand(SimpleBrand),
    Unknown,
}

impl OsGlyph {
    /// Resolve from a stored `os_id`, a WSL distro name, or a host label.
    pub fn from_hint(os_id: Option<&str>, name: &str) -> Self {
        let needle = os_id.unwrap_or(name).to_ascii_lowercase();
        if let Some(brand) = SimpleBrand::from_hint(&needle) {
            return Self::Brand(brand);
        }
        // Generic linux-ish fallback when we know it's a distro but not which.
        if os_id.is_some()
            && (needle.contains("linux")
                || needle.contains("gnu")
                || needle.contains("wsl"))
        {
            return Self::Brand(SimpleBrand::Linux);
        }
        Self::Unknown
    }

    /// Brand fill colour (non-premultiplied RGBA).
    ///
    /// Near-black brand hex (Apple, etc.) is lifted so the mark stays
    /// visible on the dark Apple HIG chrome.
    pub fn color(self) -> [f32; 4] {
        match self {
            Self::Brand(brand) => brand.color_rgba(),
            Self::Unknown => [0.55, 0.55, 0.55, 1.0],
        }
    }

    /// Lucide fallback when we have no brand mark.
    pub fn fallback_icon(self, badge_icon: Icon) -> Icon {
        badge_icon
    }

    /// Whether the painter should fill the Simple Icons path.
    pub fn has_mark(self) -> bool {
        matches!(self, Self::Brand(_))
    }

    /// Stable atlas key for the filled brand mask (disjoint from Lucide ids).
    pub fn mask_id(self) -> u64 {
        match self {
            Self::Brand(brand) => 10_000 + brand as u64,
            Self::Unknown => 10_000 + 999,
        }
    }

    /// SVG path `d` on the Simple Icons 24×24 grid (filled).
    pub fn path_d(self) -> &'static str {
        match self {
            Self::Brand(brand) => brand.path_d(),
            Self::Unknown => "",
        }
    }

    pub fn path(self) -> Vec<Cmd> {
        let d = self.path_d();
        if d.is_empty() {
            Vec::new()
        } else {
            commands(d)
        }
    }
}

impl SimpleBrand {
    /// Map free-text OS hints onto a Simple Icons brand.
    pub fn from_hint(needle: &str) -> Option<Self> {
        // Order matters: more specific needles before generic `linux`.
        let rules: &[(&[&str], Self)] = &[
            (&["nix"], Self::NixOs),
            (&["ubuntu", "kubuntu", "xubuntu", "lubuntu"], Self::Ubuntu),
            (&["debian"], Self::Debian),
            (&["fedora"], Self::Fedora),
            (&["arch"], Self::ArchLinux),
            (
                &[
                    "mac", "darwin", "sonoma", "sequoia", "ventura", "apple",
                ],
                Self::Apple,
            ),
            (&["postgres", "pgsql"], Self::Postgresql),
            (&["redhat", "rhel", "red hat"], Self::RedHat),
            (&["alpine"], Self::AlpineLinux),
            (&["centos"], Self::CentOs),
            (&["suse", "opensuse"], Self::OpenSuse),
            (&["gentoo"], Self::Gentoo),
            (&["void"], Self::VoidLinux),
            (&["rocky"], Self::RockyLinux),
            (&["kali"], Self::KaliLinux),
            (&["mint"], Self::LinuxMint),
            (&["linux"], Self::Linux),
        ];
        for (needles, brand) in rules {
            if needles.iter().any(|n| needle.contains(n)) {
                return Some(*brand);
            }
        }
        None
    }

    fn color_rgba(self) -> [f32; 4] {
        let h = self.hex();
        let parse = |i: usize| u8::from_str_radix(&h[i..i + 2], 16).unwrap_or(0x88);
        let r = parse(0) as f32 / 255.0;
        let g = parse(2) as f32 / 255.0;
        let b = parse(4) as f32 / 255.0;
        let luma = 0.2126 * r + 0.7152 * g + 0.0722 * b;
        if luma < 0.15 {
            // Apple etc. ship #000000 — lift for dark chrome.
            [0.90, 0.90, 0.92, 1.0]
        } else {
            [r, g, b, 1.0]
        }
    }
}

