/// Status for a host row in the sidebar.
///
/// Visual language: a small luminous **status dot** on the badge (see
/// [`HostStatus::dot_color`]). Card washes were retired — they fought the
/// OS glyph and made active hosts read as heavy blocks.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum HostStatus {
    #[default]
    Idle,
    /// WSL distro is running (no open Terminus tab required).
    Running,
    /// WSL distro is stopped.
    Stopped,
    /// A tab/session is open for this host (local, WSL, or SSH).
    Active,
}

impl HostStatus {
    /// Legacy card-wash tint. Always `None` — status is communicated by
    /// [`Self::dot_color`] instead.
    pub fn color(self) -> Option<[f32; 4]> {
        None
    }

    /// Luminous status-dot color (sRGB 0–1). `None` = no dot (idle).
    pub fn dot_color(self) -> Option<[f32; 4]> {
        match self {
            Self::Idle => None,
            // emerald-400
            Self::Running => Some([0x34 as f32 / 255.0, 0xd3 as f32 / 255.0, 0x99 as f32 / 255.0, 1.0]),
            // slate-500 — present but quiet
            Self::Stopped => Some([0x64 as f32 / 255.0, 0x74 as f32 / 255.0, 0x8b as f32 / 255.0, 1.0]),
            // Apple accent blue — live session
            Self::Active => Some([0x0a as f32 / 255.0, 0x84 as f32 / 255.0, 0xff as f32 / 255.0, 1.0]),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn status_dots_not_washes() {
        assert!(HostStatus::Idle.color().is_none());
        assert!(HostStatus::Active.color().is_none());
        assert!(HostStatus::Idle.dot_color().is_none());
        assert!(HostStatus::Active.dot_color().is_some());
        assert!(HostStatus::Running.dot_color().is_some());
        assert!(HostStatus::Stopped.dot_color().is_some());
    }

    #[test]
    fn local_row_resolves_os_glyph_from_endpoint_hint() {
        // Name is always "This computer"; the brand comes from os_id or subtitle.
        let from_id = OsGlyph::from_hint(Some("nixos"), "This computer");
        assert_eq!(from_id, OsGlyph::Brand(SimpleBrand::NixOs));
        let from_endpoint = OsGlyph::from_hint(None, "nixos@NixOS · WSL");
        assert_eq!(from_endpoint, OsGlyph::Brand(SimpleBrand::NixOs));
    }

    #[test]
    fn maps_common_ids() {
        assert_eq!(
            OsGlyph::from_hint(Some("nixos"), ""),
            OsGlyph::Brand(SimpleBrand::NixOs)
        );
        assert_eq!(
            OsGlyph::from_hint(None, "Ubuntu-24.04"),
            OsGlyph::Brand(SimpleBrand::Ubuntu)
        );
        assert_eq!(OsGlyph::from_hint(Some("windows"), ""), OsGlyph::Unknown);
        assert_eq!(
            OsGlyph::from_hint(Some("fedora"), ""),
            OsGlyph::Brand(SimpleBrand::Fedora)
        );
        assert_eq!(OsGlyph::from_hint(None, "01"), OsGlyph::Unknown);
    }

    #[test]
    fn brand_marks_have_paths() {
        for brand in SimpleBrand::ALL {
            let g = OsGlyph::Brand(brand);
            assert!(g.has_mark(), "{brand:?}");
            assert!(!g.path().is_empty(), "{brand:?}");
            assert_eq!(brand.hex().len(), 6, "{brand:?}");
        }
        assert!(!OsGlyph::Unknown.has_mark());
    }

    #[test]
    fn maps_macos_and_distros() {
        assert_eq!(
            OsGlyph::from_hint(Some("macos"), ""),
            OsGlyph::Brand(SimpleBrand::Apple)
        );
        assert_eq!(
            OsGlyph::from_hint(None, "macOS Sonoma"),
            OsGlyph::Brand(SimpleBrand::Apple)
        );
        assert_eq!(
            OsGlyph::from_hint(Some("arch"), ""),
            OsGlyph::Brand(SimpleBrand::ArchLinux)
        );
        assert_eq!(
            OsGlyph::from_hint(None, "postgres-replica"),
            OsGlyph::Brand(SimpleBrand::Postgresql)
        );
    }

    #[test]
    fn simple_icons_slugs_are_stable() {
        assert_eq!(SimpleBrand::NixOs.slug(), "nixos");
        assert_eq!(SimpleBrand::Ubuntu.slug(), "ubuntu");
        assert_eq!(SimpleBrand::Apple.slug(), "apple");
    }
}
